#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Registers the production GitHub App behind Solution Commits (ADR 0003) and
# switches the feature on at code-bite.com: puts the App's values into the
# server's ~/CodeBite/infra/.env over SSH, then rolls the backend replicas
# through the zero-downtime Deploy workflow.
#
# The dev App can't double as production: with "Request user authorization
# during installation" on, GitHub sends every install to the App's first
# callback URL, and the dev App's is localhost.
#
# Run from the repo root. Needs ssh access to the server and an authenticated gh.

CALLBACK_URL="https://code-bite.com/github/callback"
PROFILE_URL="https://code-bite.com/profile"

# remote_apply_script ID CLIENT_ID SLUG CLIENT_SECRET PRIVATE_KEY_BASE64 prints a
# script for the server's shell. It is piped to `ssh ... bash -s`, so the
# secrets travel over stdin and never appear in process arguments. On the
# server it backs up infra/.env, replaces every GITHUB_APP_* line with these
# five, and reports key names only.
remote_apply_script() {
  local id cid slug secret key
  printf -v id '%q' "$1"; printf -v cid '%q' "$2"; printf -v slug '%q' "$3"
  printf -v secret '%q' "$4"; printf -v key '%q' "$5"
  cat <<EOF
set -euo pipefail
cd "\${CODEBITE_DIR:-\$HOME/CodeBite}"
f=infra/.env
[ -f "\$f" ] || { echo "no \$PWD/\$f on this host" >&2; exit 1; }
backup="\$f.bak-\$(date -u +%Y%m%dT%H%M%SZ)"
cp -p "\$f" "\$backup"
{
  grep -vE '^(export )?GITHUB_APP_[A-Z0-9_]+=' "\$f" || true
  printf 'export GITHUB_APP_ID=%s\n' $id
  printf 'export GITHUB_APP_CLIENT_ID=%s\n' $cid
  printf 'export GITHUB_APP_SLUG=%s\n' $slug
  printf 'export GITHUB_APP_CLIENT_SECRET=%s\n' $secret
  printf 'export GITHUB_APP_PRIVATE_KEY_BASE64=%s\n' $key
} > "\$f.new"
cat "\$f.new" > "\$f"
rm -f "\$f.new"
echo "backed up \$f to \$backup"
echo "wrote GITHUB_APP_ID GITHUB_APP_CLIENT_ID GITHUB_APP_SLUG GITHUB_APP_CLIENT_SECRET GITHUB_APP_PRIVATE_KEY_BASE64"
EOF
}

run_wizard() {

TOTAL_STAGES=7
# Only non-secret values (App ID, Client ID, slug, SSH target) are saved, outside
# the repo, so a re-run can keep them. The client secret and key stay in memory.
ENV_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/codebite/github-app-prod.env"
mkdir -p "$(dirname "$ENV_FILE")"
RESULTS=()
record() {
  if confirm "$1"; then RESULTS+=("PASS  $1"); else RESULTS+=("FAIL  $1"); SKIPPED+=("investigate: $1"); fi
}

banner "CodeBite: switch on Solution Commits in production"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Register the production GitHub App"
say "Same shape as the dev App; the ★ lines are what production changes."
open_url "https://github.com/settings/apps/new"
step "GitHub App name: CodeBite Solutions   (names are global; users see it when installing)"
step "★ Homepage URL: https://code-bite.com"
step "★ Identifying and authorizing users → Callback URL: $CALLBACK_URL   (the only one)"
step "Keep 'Expire user authorization tokens' ticked"
step "Tick 'Request user authorization (OAuth) during installation'"
step "Leave 'Enable Device Flow' unticked (Setup URL greys out, which is expected)"
step "Webhook → untick 'Active'"
step "Permissions → Repository permissions → Contents → Read and write"
note "  (Metadata: Read-only is added automatically; leave everything else 'No access')"
step "★ Where can this GitHub App be installed? → Any account   (otherwise only you can install it)"
step "Click 'Create GitHub App'"
step "★ Optional, on the next page: upload a logo and add a description; users see both"
pause "Press Enter once the app's General settings page is open"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "App ID, Client ID and slug"
say "All three are on the app's General page, under 'About'. None of them is secret."
step "Copy the App ID (a number)"
ask GITHUB_APP_ID "App ID:"
until [[ "$GITHUB_APP_ID" =~ ^[0-9]+$ ]]; do warn "the App ID is a number"; ask GITHUB_APP_ID "App ID:"; done
step "Copy the Client ID (starts with Iv)"
ask GITHUB_APP_CLIENT_ID "Client ID:"
step "Copy the Public link (https://github.com/apps/<slug>), or just the slug"
ask GITHUB_APP_SLUG "Public link or slug:"
GITHUB_APP_SLUG="${GITHUB_APP_SLUG#https://github.com/apps/}"
GITHUB_APP_SLUG="${GITHUB_APP_SLUG%/}"
for k in GITHUB_APP_ID GITHUB_APP_CLIENT_ID GITHUB_APP_SLUG; do write_env "$k" "${!k}"; done
note "Install URL will be: https://github.com/apps/$GITHUB_APP_SLUG/installations/new"
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Client secret"
step "On the same page, under 'Client secrets', click 'Generate a new client secret'"
step "Copy it now: GitHub shows it only once"
GITHUB_APP_CLIENT_SECRET=""
until [[ "$GITHUB_APP_CLIENT_SECRET" =~ ^[A-Za-z0-9_-]+$ ]]; do
  [[ -n "$GITHUB_APP_CLIENT_SECRET" ]] && warn "that doesn't look like a client secret (letters and digits only); paste it again"
  ask_secret GITHUB_APP_CLIENT_SECRET "Client secret (hidden, kept in memory only):"
done
note "held in memory; it goes only to the server"
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Private key"
step "Scroll to 'Private keys' at the bottom and click 'Generate a private key'"
step "Your browser downloads a .pem file (usually into ~/Downloads)"
pem=""
while :; do
  read -e -r -p "  ${BOLD}Path to the downloaded .pem:${RESET} " pem || exit 1
  pem="${pem/#\~/$HOME}"
  if [[ -f "$pem" ]] && grep -q "BEGIN RSA PRIVATE KEY" "$pem"; then break; fi
  warn "that isn't a readable GitHub App private key; try again"
done
GITHUB_APP_PRIVATE_KEY_BASE64="$(base64 < "$pem" | tr -d '\n')"
note "read and base64-encoded in memory"
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Put the values on the server"
say "The deploy keeps the app in ~/CodeBite on the server; its infra/.env holds production config."
ask SSH_TARGET "SSH target for the server (user@host or an ~/.ssh/config alias):"
write_env SSH_TARGET "$SSH_TARGET"
until ssh -o BatchMode=yes -o ConnectTimeout=10 "$SSH_TARGET" 'test -f ~/CodeBite/infra/.env'; do
  warn "can't reach ~/CodeBite/infra/.env over ssh $SSH_TARGET"
  ask SSH_TARGET "SSH target (fix the target, or check your key with: ssh $SSH_TARGET):"
  write_env SSH_TARGET "$SSH_TARGET"
done
note "reached ~/CodeBite/infra/.env on $SSH_TARGET"
say "This backs up the server's infra/.env, then replaces its GITHUB_APP_* lines."
if confirm "Write the five GITHUB_APP_* values on $SSH_TARGET now?"; then
  remote_apply_script "$GITHUB_APP_ID" "$GITHUB_APP_CLIENT_ID" "$GITHUB_APP_SLUG" \
      "$GITHUB_APP_CLIENT_SECRET" "$GITHUB_APP_PRIVATE_KEY_BASE64" \
    | ssh -o BatchMode=yes "$SSH_TARGET" bash -s \
    | while IFS= read -r line; do note "server: $line"; done
  applied=true
else
  applied=false
  SKIPPED+=("put the GITHUB_APP_* values in the server's infra/.env, then re-run")
fi
pause

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Roll the backend"
if ! $applied; then
  warn "nothing was written to the server, so there is nothing to roll out"
elif ! command -v gh >/dev/null 2>&1; then
  warn "gh is not installed"
  SKIPPED+=("run the Deploy workflow (Actions → Deploy → Run workflow) to restart the backend")
else
  say "The Deploy workflow starts new backend replicas, which read the updated .env,"
  say "and stops the old ones only once the new ones are healthy: no downtime."
  if confirm "Run the Deploy workflow on master now?"; then
    gh workflow run deploy.yml --ref master
    sleep 5
    run_id=$(gh run list --workflow deploy.yml --branch master --event workflow_dispatch \
      --limit 1 --json databaseId --jq '.[0].databaseId')
    note "watching deploy run $run_id (takes a few minutes)"
    if gh run watch "$run_id" --interval 20 --exit-status >/dev/null; then
      note "deploy succeeded"
    else
      warn "deploy failed; it rolls back on its own. See: gh run view $run_id --log-failed"
      SKIPPED+=("fix the failed deploy run $run_id")
    fi
  else
    SKIPPED+=("run the Deploy workflow to restart the backend with the new values")
  fi
fi
pause

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Smoke test on code-bite.com"
if $applied; then
  step "Create a scratch public repository with a README (https://github.com/new)"
  open_url "$PROFILE_URL"
  step "GitHub Link card → Link GitHub: it should open github.com/apps/$GITHUB_APP_SLUG/installations/new"
  step "Install on 'Only select repositories' → the scratch repository → Install & Authorize"
  record "Linking lands back on the profile showing the scratch repository"
  step "Solve any problem until Accepted, then open its submission detail"
  record "The submission shows Committed, and the commit is authored as you"
else
  warn "skipped: the server doesn't have the App's values yet"
fi
if confirm "Delete the downloaded key $pem? (the server has it; you can generate a new one any time)"; then
  rm -f "$pem" && note "deleted $pem"
else
  SKIPPED+=("delete or safely store $pem")
fi

finish
if (( ${#RESULTS[@]} )); then
  say "Smoke test:"
  for r in "${RESULTS[@]}"; do note "  $r"; done
fi
say "Users can now link GitHub from their profile. Delete the scratch repository if you like."
printf '\n'
}

run_wizard "$@"; exit
